items.solution_code:
def average(*numbers):
    if len(numbers) == 0:
        raise ValueError('At least one number is required')
    return sum(numbers) / len(numbers)

print(average(2, 4))
print(average(1, 2, 3))
print(average(10, 20, 30, 40))
